package dev.zomboid.decor;
import java.lang.reflect.Proxy;
import java.util.*;
public final class Cooling {
 static boolean fridge(Object be){String id=Storage.id(R.call(be,"getBlockState"));return id.startsWith("fridge")||id.startsWith("vendingmachine")||id.equals("insulationcabinet");}
 static boolean drink(Object s){return !R.yes(R.call(s,"isEmpty"))&&R.call(s,"getUseAnimation").toString().equals("DRINK");}
 static String item(Object s){return R.call(R.get(R.type("net.minecraft.core.registries.BuiltInRegistries"),"ITEM"),"getKey",R.call(s,"getItem")).toString();}
 static int fuel(Object s){if(R.yes(R.call(s,"isEmpty")))return 0;return switch(item(s)){case "minecraft:ice"->1200;case "minecraft:packed_ice"->6000;case "minecraft:blue_ice"->12000;default->0;};}
 public static boolean accepts(Object be,int slot,Object stack){if(R.yes(R.get(be,"ddPart")))return false;if(!fridge(be))return true;return slot==Storage.size(be)-1?fuel(stack)>0:drink(stack);}
 public static Object menu(Object be,int n,Object inv){Object menu=Storage.menu(be,n,inv);if(fridge(be)){List<Object> slots=(List<Object>)R.get(menu,"slots");for(int i=0;i<Storage.size(be);i++){Object old=slots.get(i);Object s=R.make("dev.zomboid.decor.DrinkSlot",be,i,R.get(old,"x"),R.get(old,"y"));R.set(s,"index",i);slots.set(i,s);}}return menu;}
 public static Object ticker(Object level,Object state){String id=Storage.id(state);if(R.yes(R.call(level,"isClientSide"))||!(id.startsWith("fridge")||id.startsWith("vendingmachine")||id.equals("insulationcabinet")))return null;Class<?> type=R.type("net.minecraft.world.level.block.entity.BlockEntityTicker");return Proxy.newProxyInstance(type.getClassLoader(),new Class[]{type},(p,m,a)->{if(m.getName().equals("tick")){tick(a[0],a[3]);return null;}if(m.getName().equals("toString"))return "Doomsday cooler ticker";if(m.getName().equals("hashCode"))return System.identityHashCode(p);if(m.getName().equals("equals"))return p==a[0];return null;});}
 static boolean generator(Object world,Object p){try{Class<?> c=R.type("dev.zomboid.survival.MachineEntity");Map<?,?> all=(Map<?,?>)R.get(c,"GENERATORS");Object gen=all.get(world);if(!(gen instanceof Set<?> set))return false;for(Object q:set){if(!R.yes(R.call(world,"hasChunkAt",q)))continue;double dx=R.coord(q,"X")-R.coord(p,"X"),dy=R.coord(q,"Y")-R.coord(p,"Y"),dz=R.coord(q,"Z")-R.coord(p,"Z");if(dx*dx+dy*dy+dz*dz>625)continue;Object be=R.call(world,"getBlockEntity",q);if(be==null)continue;Object energy=R.get(be,"energy");if(((Number)R.call(energy,"extractEnergy",20,true)).intValue()==20){R.call(energy,"extractEnergy",20,false);R.call(be,"setChanged");return true;}}}catch(Exception absent){}return false;}
 public static void tick(Object world,Object be){if(R.yes(R.get(be,"ddPart"))||!fridge(be)||R.get(be,"lootTable")!=null)return;long now=R.lng(R.call(world,"getGameTime"));if(now<R.lng(R.get(be,"ddNextTick")))return;R.set(be,"ddNextTick",now+20);Object p=R.call(be,"getBlockPos");int ice=((Number)R.get(be,"ddIce")).intValue();boolean powered=generator(world,p);if(!powered){if(ice<=0){Object s=R.call(be,"getItem",Storage.size(be)-1);ice=fuel(s);if(ice>0)R.call(s,"shrink",1);}powered=ice>0;if(powered)ice=Math.max(0,ice-20);}R.set(be,"ddIce",ice);int chill=((Number)R.get(be,"ddChill")).intValue();chill=powered?Math.min(200,chill+20):0;R.set(be,"ddChill",chill);if(chill==200){for(int i=0;i<Storage.size(be)-1;i++){Object s=R.call(be,"getItem",i);if(!drink(s))continue;Object component=R.get(R.type("net.minecraft.core.component.DataComponents"),"CUSTOM_DATA");Object custom=R.call(s,"get",component),tag=custom==null?R.make("net.minecraft.nbt.CompoundTag"):R.call(custom,"copyTag");Object clock=R.call(tag,"getCompound","zomboid_food");R.call(clock,"putInt","cold",1200);R.call(clock,"putLong","last",now);if(!R.yes(R.call(clock,"contains","rate")))R.call(clock,"putInt","rate",1);R.call(tag,"put","zomboid_food",clock);R.call(s,"set",component,R.call(R.type("net.minecraft.world.item.component.CustomData"),"of",tag));}if(now%100==0)R.call(world,"playSound",null,p,R.get(R.type("net.minecraft.sounds.SoundEvents"),"BEACON_AMBIENT"),R.get(R.type("net.minecraft.sounds.SoundSource"),"BLOCKS"),.2f,1.6f);}R.call(be,"setChanged");}
 public static void register(Object e){Object key=R.get(R.type("net.minecraft.core.registries.Registries"),"BLOCK");if(!key.equals(R.call(e,"getRegistryKey")))return;Object spec=R.make("net.mcreator.doomsdaydecoration.port.BlockSpec");R.set(spec,"id","interaction_part");R.set(spec,"type","Block");R.set(spec,"zero_light_block",true);R.set(spec,"visual_shape_empty",true);R.set(spec,"dynamic_shape",true);R.set(spec,"shapes",Map.of("all",new double[0][]));Storage.before(spec);Object props=R.call(R.type("net.minecraft.world.level.block.state.BlockBehaviour$Properties"),"of");R.call(props,"noOcclusion");R.call(props,"dynamicShape");R.call(props,"strength",1f);R.call(props,"pushReaction",R.get(R.type("net.minecraft.world.level.material.PushReaction"),"BLOCK"));PART(spec,props);Object id=R.call(R.type("net.minecraft.resources.ResourceLocation"),"fromNamespaceAndPath","doomsday_decoration","interaction_part");R.call(e,"register",key,id,(java.util.function.Supplier<Object>)()->Footprint.PART);}
 static void PART(Object spec,Object props){Footprint.PART=R.make("net.mcreator.doomsdaydecoration.block.PortedAcrateBlock",spec,props);}
}
